
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.077792726980115e-02, -5.049233590599581e-02, -5.007158024225839e-02, -4.944560845961198e-02, -4.850206408165758e-02, -4.705626548658514e-02, -4.480212463201937e-02, -4.126306160406382e-02, -3.595930900529136e-02, -3.006808720057942e-02, -3.460315314117948e-02, -5.633568522467695e-02, -3.868884703665781e-02, -2.647845723044428e-02, -1.648256765911887e-02, -7.895606726805775e-03, -2.970431494111652e-03, -1.216720595114125e-03, -6.191606706034415e-04, -2.015654714636038e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


